  const int r3 = wrap_y(y0 - 1);
  const int r4 = wrap_y(y0);
  const int r5 = wrap_y(y0 + 1);
  const int r6 = wrap_y(y0 + 2);
  const int r7 = wrap_y(y0 + 3);
  const int r8 = wrap_y(y0 + 4);
  const int r9 = wrap_y(y0 + 5);

